def min_rows_to_mirror(a):
    n, m = len(a), len(a[0])
    seen = set()
    for i in range(n // 2):
        top_half = tuple(a[i][:])
        bottom_half = tuple(a[n - i - 1][:])
        if bottom_half != top_half[::-1]:
            return 2 * (i + 1)
        seen.update(top_half)
    if n % 2 == 1 and tuple(a[n // 2]) in seen:
        return n
    return 2 * (n // 2 + 1)

import sys
input = sys.stdin.read
data = input().split()

n = int(data[0])
m = int(data[1])
a = [list(map(int, data[2 + i * m : 2 + (i + 1) * m])) for i in range(n)]

print(min_rows_to_mirror(a))
